import React from "react";
import { Link } from "react-router-dom";

const IMG = "https://static.wixstatic.com/media/5473a8_24998360f4e04f3a990db6f116e3190b~mv2.jpg/v1/fill/w_640,h_400,al_c,q_80,usm_0.66_1.00_0.01,enc_avif,quality_auto/5473a8_24998360f4e04f3a990db6f116e3190b~mv2.jpg";

export default function Landing() {
  return (
    <div style={{
      minHeight: "calc(100vh - 68px)",
      backgroundImage: `url('${IMG}')`,
      backgroundSize: "cover",
      backgroundPosition: "center",
      position: "relative",
      display: "flex",
      alignItems: "center",
    }}>
      {/* Ivy green overlay — 0.68 opacity so building shows through */}
      <div style={{
        position: "absolute", inset: 0,
        background: "rgba(13,59,46,0.68)",
      }} />

      {/* Content */}
      <div style={{ position: "relative", zIndex: 1, maxWidth: 1200, margin: "0 auto", padding: "6rem 2rem", width: "100%" }}>
        <div className="overline" style={{ marginBottom: 20, color: "#e8a898" }}>
          The College Alumnae Network — Est. 2026
        </div>
        <h1 className="font-serif" style={{
          fontSize: "clamp(2.5rem, 6vw, 5rem)",
          color: "#fff",
          lineHeight: 1.08,
          maxWidth: 820,
          marginBottom: "1.5rem",
        }}>
          Where the people who built you <em>help you build what's next.</em>
        </h1>
        <p style={{ color: "rgba(255,255,255,0.82)", maxWidth: 520, margin: "0 0 2.5rem", lineHeight: 1.75, fontSize: "1.05rem" }}>
          A private, intentional space for students and alumni to find one another — for mentorship, for opportunity, for conversation that actually leads somewhere.
        </p>
        <div style={{ display: "flex", gap: 16 }}>
          <Link to="/register">
            <button className="btn-accent" style={{ fontSize: "1rem", padding: "0.8rem 2rem" }}>
              Request Your Invitation →
            </button>
          </Link>
          <Link to="/login">
            <button style={{
              background: "transparent",
              border: "1px solid rgba(255,255,255,0.6)",
              color: "#fff",
              padding: "0.8rem 2rem",
              fontSize: "1rem",
              cursor: "pointer",
            }}>
              Sign In
            </button>
          </Link>
        </div>
      </div>
    </div>
  );
}
